#!/usr/bin/env node
// tools/build_progress.mjs — the player-facing progress page.
//
// Reads <root>/web/system-status.json (generated by tools/build_system_status.mjs)
// and writes <root>/PROGRESS.md plus the summary block between the
// `<!-- progress:start -->` / `<!-- progress:end -->` markers in <root>/README.md.
// Every number comes from system-status.json; this script only adds plain-English
// names. `--check` exits 1 if either file is stale instead of writing.
//
//   node tools/build_progress.mjs public-overlay          # walker: refresh the export's copy
//   node tools/build_progress.mjs . --check               # export: freshness check
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";

const args = process.argv.slice(2);
const check = args.includes("--check");
const root = args.find((a) => !a.startsWith("--")) ?? ".";

// Player-facing name and group for each system id in system-status.json.
// A system missing here still appears, under its id, so nothing is dropped silently.
const NAMES = {
  "world-exploration": ["Exploring the world (maps, doors, people)", "Story & world"],
  "story-gating": ["Story progression", "Story & world"],
  "quest-events": ["Quests and story events", "Story & world"],
  "random-encounters": ["Random encounters", "Story & world"],
  "save-load": ["Saving and loading", "Story & world"],
  "inn": ["Inns", "Story & world"],
  "shops": ["Shops", "Story & world"],
  "fishing": ["Fishing", "Story & world"],
  "gym-training": ["Gym training", "Story & world"],
  "arena-tournaments": ["Arena tournaments", "Story & world"],
  "card-battle": ["Card battles", "Story & world"],
  "post-game": ["Post-game content", "Story & world"],
  "battle": ["Battles", "Battles & Digimon"],
  "technique-loading": ["Techniques", "Battles & Digimon"],
  "status-effects": ["Status effects", "Battles & Digimon"],
  "elemental": ["Elements and weaknesses", "Battles & Digimon"],
  "exp-leveling": ["EXP and leveling up", "Battles & Digimon"],
  "stat-growth": ["Stat growth", "Battles & Digimon"],
  "digivolution": ["Digivolution", "Battles & Digimon"],
  "blast-digivolution": ["Blast digivolution", "Battles & Digimon"],
  "dna-digivolution": ["DNA digivolution", "Battles & Digimon"],
  "party-management": ["Party management", "Battles & Digimon"],
  "items": ["Items", "Battles & Digimon"],
  "equipment": ["Equipment", "Battles & Digimon"],
  "charisma": ["Charisma", "Battles & Digimon"],
  "audio": ["Music and sound", "Look & sound"],
  "ui-chrome": ["Menus and windows", "Look & sound"],
  "battle-3d": ["3D battle scenes", "Look & sound"],
  "rendering-2d": ["2D graphics", "Look & sound"],
  "field-character-shadow": ["Character shadows", "Look & sound"],
  "input": ["Controls", "Under the hood"],
  "resident-core": ["Core engine", "Under the hood"],
  "engine-resource": ["Loading game resources", "Under the hood"],
  "battle-model-data": ["Battle model data", "Under the hood"],
};
const GROUPS = ["Story & world", "Battles & Digimon", "Look & sound", "Under the hood", "Other"];
const SCORE = { implemented: 1, partial: 0.5, missing: 0 };
const LABEL = { implemented: "✅ Works", partial: "🟡 Partly works", missing: "⬜ Not yet" };

const status = JSON.parse(readFileSync(join(root, "web/system-status.json"), "utf8"));
const systems = status.systems.filter((s) => s.wired?.status in SCORE);
const count = (st) => systems.filter((s) => s.wired.status === st).length;
const pct = (n, d) => (d ? Math.round((100 * n) / d) : 0);
const overall = pct(systems.reduce((a, s) => a + SCORE[s.wired.status], 0), systems.length);
const sc = status.screens ?? {};
const screensDone = sc.done?.length ?? 0;
const screensTotal = ["done", "inProgress", "next", "open"].reduce((a, k) => a + (sc[k]?.length ?? 0), 0);
const t = status.totals;

const bar = (p) => "█".repeat(Math.round(p / 10)) + "░".repeat(10 - Math.round(p / 10));

const summary = [
  `**Overall: about ${overall}% of the game's systems work** ${bar(overall)}`,
  "",
  `- ${count("implemented")} of ${systems.length} systems work fully, ${count("partial")} work partly${count("missing") ? `, ${count("missing")} not yet` : ""}.`,
  `- ${screensDone} of ${screensTotal} game screens are rebuilt from the original game's code (${pct(screensDone, screensTotal)}%).`,
  `- ${pct(t.verified, t.claims)}% of the ${t.claims} documented facts about the original game are fully checked against its code.`,
  "",
  "Per-feature breakdown: [PROGRESS.md](PROGRESS.md).",
].join("\n");

const rows = (group) =>
  systems
    .filter((s) => (NAMES[s.id]?.[1] ?? "Other") === group)
    .sort((a, b) => SCORE[b.wired.status] - SCORE[a.wired.status] || (NAMES[a.id]?.[0] ?? a.id).localeCompare(NAMES[b.id]?.[0] ?? b.id))
    .map((s) => {
      const l = s.learned ?? {};
      const checked = l.claims ? `${pct(l.verified, l.claims)}% (${l.verified}/${l.claims})` : "—";
      return `| ${NAMES[s.id]?.[0] ?? s.id} | ${LABEL[s.wired.status]} | ${checked} |`;
    });

const page = [
  "# Progress",
  "",
  "How much of Digimon World 2003 this recreation already does. This page is",
  "generated from `web/system-status.json` by `tools/build_progress.mjs`; do not",
  "edit it by hand.",
  "",
  summary.replace("\n\nPer-feature breakdown: [PROGRESS.md](PROGRESS.md).", ""),
  "",
  "## How to read this",
  "",
  "- **✅ Works**: the feature is in the game and runs the way the original does,",
  "  as far as we have found. Bugs are still possible.",
  "- **🟡 Partly works**: the feature is in the game, but parts of it are missing",
  "  or simplified.",
  "- **Checked against the original**: of the facts we have written down about how",
  "  the original does this feature, the share that has been fully confirmed",
  "  against the original game's code. A low number means less has been double",
  "  checked, not that it is broken.",
  "- **Overall %**: every system counts the same; a working one counts 1, a",
  "  partly working one ½. It is a rough guide, not a measurement of play time.",
  "",
  ...GROUPS.flatMap((g) => {
    const r = rows(g);
    return r.length ? [`## ${g}`, "", "| Feature | Status | Checked against the original |", "| --- | --- | --- |", ...r, ""] : [];
  }),
  "The engineering view of the same data (every claim, test and code file) is the",
  "systems page: open `systems.html` in the running game.",
  "",
].join("\n");

const readmePath = join(root, "README.md");
const readme = existsSync(readmePath) ? readFileSync(readmePath, "utf8") : "";
const re = /(<!-- progress:start -->\n)[\s\S]*?(<!-- progress:end -->)/;
if (!re.test(readme)) {
  console.error(`build_progress: ${readmePath} has no <!-- progress:start --> … <!-- progress:end --> block`);
  process.exit(2);
}
const newReadme = readme.replace(re, `$1${summary}\n$2`);
const progressPath = join(root, "PROGRESS.md");
const oldPage = existsSync(progressPath) ? readFileSync(progressPath, "utf8") : "";

if (check) {
  const stale = [oldPage !== page && "PROGRESS.md", newReadme !== readme && "README.md"].filter(Boolean);
  if (stale.length) {
    console.error(`build_progress: stale: ${stale.join(", ")} — run node tools/build_progress.mjs ${root}`);
    process.exit(1);
  }
  console.log("build_progress: up to date");
} else {
  writeFileSync(progressPath, page);
  writeFileSync(readmePath, newReadme);
  console.log(`build_progress: overall ${overall}% (${count("implemented")} work, ${count("partial")} partly, of ${systems.length}); wrote ${progressPath} and the README block`);
}
